//! TODO business operations backed by a JSON file.
use serde::{Deserialize, Serialize};
use std::{
    fmt,
    fs::File,
    io,
    path::{Path, PathBuf},
};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Task {
    pub id: u64,
    pub description: String,
    pub completed: bool,
}

#[derive(Debug)]
pub enum Error {
    Io(io::Error),
    Json(serde_json::Error),
    NotFound(u64),
    IdExhausted,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(error) => write!(f, "task storage: {error}"),
            Self::Json(error) => write!(f, "invalid task JSON: {error}"),
            Self::NotFound(id) => write!(f, "task {id} does not exist"),
            Self::IdExhausted => write!(f, "task identifiers exhausted"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Io(e) => Some(e),
            Self::Json(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for Error {
    fn from(error: io::Error) -> Self {
        Self::Io(error)
    }
}
impl From<serde_json::Error> for Error {
    fn from(error: serde_json::Error) -> Self {
        Self::Json(error)
    }
}

#[derive(Serialize, Deserialize)]
struct State {
    next_id: u64,
    tasks: Vec<Task>,
}

/// Filesystem boundary. Each operation reads current storage; mutations save
/// before returning success. Concurrent writers are outside this API's contract.
pub struct TodoStore {
    path: PathBuf,
}

impl TodoStore {
    /// Normal app storage, independent of the process's working directory.
    pub fn project() -> Self {
        Self::at(Path::new(env!("CARGO_MANIFEST_DIR")).join("tasks.json"))
    }

    /// Select storage explicitly, for example for a separate collection.
    pub fn at(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into() }
    }

    /// List tasks in creation order. Missing storage is an empty collection.
    pub fn list(&self) -> Result<Vec<Task>, Error> {
        Ok(self.load()?.tasks)
    }

    pub fn create(&self, description: impl Into<String>) -> Result<Task, Error> {
        let mut state = self.load()?;
        let id = state.next_id;
        state.next_id = id.checked_add(1).ok_or(Error::IdExhausted)?;
        let task = Task {
            id,
            description: description.into(),
            completed: false,
        };
        state.tasks.push(task.clone());
        self.save(&state)?;
        Ok(task)
    }

    /// Completing an already completed task succeeds without changing it.
    pub fn complete(&self, id: u64) -> Result<Task, Error> {
        let mut state = self.load()?;
        let task = state
            .tasks
            .iter_mut()
            .find(|task| task.id == id)
            .ok_or(Error::NotFound(id))?;
        task.completed = true;
        let result = task.clone();
        self.save(&state)?;
        Ok(result)
    }

    /// Remove the task and return its last state.
    pub fn delete(&self, id: u64) -> Result<Task, Error> {
        let mut state = self.load()?;
        let index = state
            .tasks
            .iter()
            .position(|task| task.id == id)
            .ok_or(Error::NotFound(id))?;
        let task = state.tasks.remove(index);
        self.save(&state)?;
        Ok(task)
    }

    fn load(&self) -> Result<State, Error> {
        match File::open(&self.path) {
            Ok(file) => Ok(serde_json::from_reader(file)?),
            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(State {
                next_id: 1,
                tasks: Vec::new(),
            }),
            Err(error) => Err(error.into()),
        }
    }

    fn save(&self, state: &State) -> Result<(), Error> {
        let parent = self
            .path
            .parent()
            .filter(|path| !path.as_os_str().is_empty())
            .unwrap_or(Path::new("."));
        let mut temporary = tempfile::NamedTempFile::new_in(parent)?;
        serde_json::to_writer_pretty(temporary.as_file_mut(), state)?;
        temporary
            .persist(&self.path)
            .map_err(|error| Error::Io(error.error))?;
        Ok(())
    }
}
